<template>
  <layout-page>
    <div class="row">
      <div class="col-12 ps-4 pt-3 ">
        <div class="float-start">
          <h5>Adicionar Produtos</h5>
        </div>
        <div class="float-end">
          <button-widget cor="azul" :href="'../index/'+tabela_preco_id" tamanho="M">
            Voltar
          </button-widget>
        </div>
      </div>

    </div>
    <div class="row">
      <FormTabelaPrecosProdutos></FormTabelaPrecosProdutos>
      <div class="col-4">
        <button class="btn btn-primary mt-4" type="button" @click="sendForm">Salvar</button>
      </div>
    </div>
  </layout-page>
</template>
<script>
import ButtonWidget from "@/components/widget/buttonWidget.vue";
import LayoutPage from "@/components/page/layoutPage.vue";
import FormTabelaPrecosProdutos from "@/views/tabela_precos_produtos/FormTabelaPrecosProdutos.vue";
import tabela_precos_produtoService from "@/services/tabela_precos_produto.service";
import toastr from "toastr/build/toastr.min";

export default {
  name: "CreateTabelaPrecosProdutos",
  components: {FormTabelaPrecosProdutos, LayoutPage, ButtonWidget},
  data() {
    return {
      tabela_preco_id: null
    }
  },
  methods: {
    async sendForm() {
      let dataForm = {
        produto_id: document.getElementById('produto_id').value,
        tabela_preco_id: this.$route.params.id,
        valor_minimo: document.getElementById('valor_minimo').value,
        desconto_maximo: document.getElementById('desconto_maximo').value,
      }
      let tabela_precos_produtosService = new tabela_precos_produtoService();
      let response = await tabela_precos_produtosService.store(dataForm);

      if (response.data?.id) {
        location.href = '/tabela_precos_produtos/index/' + this.$route.params.id;
      } else {
        if (response.response.data?.message) {
          toastr.error(response.response.data?.message);
        } else {
          toastr.error('Houve um problema ao inserir');
        }

      }
    },
    initCreateTabelaPrecosProdutos() {
      this.tabela_preco_id = this.$route.params.id;
    }
  },
  mounted() {
    this.initCreateTabelaPrecosProdutos()
  }
}
</script>
