<template>
  <layout-page>
    <div class="row">
      <div class="col-12 ps-4 pt-3 ">
        <div class="float-start">
          <h5>Editar Unidades</h5>
        </div>
        <div class="float-end">
          <button-widget cor="azul" href="../index" tamanho="M">
            Voltar
          </button-widget>
        </div>
      </div>

    </div>
    <div class="row">
      <FormUnidades></FormUnidades>
      <div class="col-4">
        <button class="btn btn-primary mt-4" type="button" @click="sendForm">Salvar</button>
      </div>
    </div>
  </layout-page>

</template>

<script>
import FormUnidades from "@/views/unidades/FormUnidades.vue";
import ButtonWidget from "@/components/widget/buttonWidget.vue";
import LayoutPage from "@/components/page/layoutPage.vue";
import toastr from "toastr/build/toastr.min";
import unidadeService from "@/services/unidade.service";

export default {
  name: "EditUnidades",
  components: {LayoutPage, ButtonWidget, FormUnidades},
  methods: {
    async edit(id) {
      let unidadesService = new unidadeService();
      let response = await unidadesService.view(id);
      document.getElementById('nome').value = response.data.nome;
      document.getElementById('descritivo').value = response.data.descritivo;
      document.getElementById('codigo_unidade').value = response.data.codigo_unidade;
      document.getElementById('cnpj_unidade').value = response.data.cnpj_unidade;
      document.getElementById('cpf_titular').value = response.data.cpf_titular;
      document.getElementById('ie_unidade').value = response.data.ie_unidade;
      document.getElementById('rg_titular').value = response.data.rg_titular;
      document.getElementById('telefone_principal').value = response.data.telefone_principal;
      document.getElementById('telefone_secundario').value = response.data.telefone_secundario;
      document.getElementById('email_principal').value = response.data.email_principal;
      document.getElementById('email_secundario').value = response.data.email_secundario;
      document.getElementById('tipo').value = response.data.tipo;
      document.getElementById('ativo').value = response.data.ativo;
      document.getElementById('grupo_id').value = response.data.grupo_id;
      document.getElementById('categoria_id').value = response.data.categoria_id;
      document.getElementById('mercadopago_public_token').value = response.data.mercadopago_public_token;
      document.getElementById('mercadopago_access_token').value = response.data.mercadopago_access_token;

    },
    async sendForm() {
      let dataForm = {
        nome: document.getElementById('nome').value,
        descritivo: document.getElementById('descritivo').value,
        codigo_unidade: document.getElementById('codigo_unidade').value,
        cnpj_unidade: document.getElementById('cnpj_unidade').value,
        cpf_titular: document.getElementById('cpf_titular').value,
        ie_unidade: document.getElementById('ie_unidade').value,
        rg_titular: document.getElementById('rg_titular').value,
        telefone_principal: document.getElementById('telefone_principal').value,
        telefone_secundario: document.getElementById('telefone_secundario').value,
        email_principal: document.getElementById('email_principal').value,
        email_secundario: document.getElementById('email_secundario').value,
        tipo: document.getElementById('tipo').value,
        ativo: document.getElementById('ativo').value,
        grupo_id: document.getElementById('grupo_id').value,
        categoria_id: document.getElementById('categoria_id').value,
        mercadopago_access_token: document.getElementById('mercadopago_access_token').value,
        mercadopago_public_token: document.getElementById('mercadopago_public_token').value,

        _method: 'PUT'

      }
      if (!dataForm.parent_id) {
        delete dataForm.parent_id
      }
      let id = this.$route.params.id;
      let unidadesService = new unidadeService();
      let response = await unidadesService.update(dataForm, id);
      if (response.data?.id) {
        toastr.success('Salvo com sucesso')
      } else {
        if (response.response.data?.message) {
          toastr.error(response.response.data?.message);
        } else {
          toastr.error('Houve um problema ao inserir');
        }

      }
    }
  },
  created() {
    this.edit(this.$route.params.id)
  }
}
</script>

