<template>
  <layout-page>
    <div class="row">
      <div class="col-12 ps-4 pt-3 ">
        <div class="float-start">
          <h5>Adicionar Contas</h5>
        </div>
        <div class="float-end">
          <button-widget cor="azul" :href="'/contas/index/'+tipo" tamanho="M">
            Voltar
          </button-widget>
        </div>
      </div>

    </div>
    <div class="row">
      <FormContas></FormContas>
      <div class="col-4">
        <button class="btn btn-primary mt-4" type="button" @click="sendForm">Salvar</button>
      </div>
    </div>
  </layout-page>
</template>
<script>
import ButtonWidget from "@/components/widget/buttonWidget.vue";
import LayoutPage from "@/components/page/layoutPage.vue";
import FormContas from "@/views/contas/FormContas.vue";
import contaService from "@/services/conta.service";
import toastr from "toastr/build/toastr.min";

export default {
  name: "CreateContas",
  components: {FormContas, LayoutPage, ButtonWidget},
  data(){
    return {
      tipo:null
    }
  },
  methods: {
    async sendForm() {
      let dataForm = {
        pessoa_id: document.getElementById('pessoa_id').value,
        descritivo: document.getElementById('descritivo').value,
        tipo: this.$route.params.tipo,
        estado: document.getElementById('estado').value,
        parcelas: document.getElementById('parcelas').value,
        valor: document.getElementById('valor').value,




      }
      let contasService = new contaService();
      let response = await contasService.store(dataForm);

      if (response.data?.id) {
        location.href = '/contas/index/'+ this.$route.params.tipo;
      } else {
        if (response.response.data?.message) {
          toastr.error(response.response.data?.message);
        } else {
          toastr.error('Houve um problema ao inserir');
        }

      }
    }
  },
  mounted() {
    this.tipo =  this.$route.params.tipo;
  }
}
</script>
