<template>
  <layout-page>
    <div class="row">
      <div class="col-12">
        <div class="row">
          <div class="col-12 ps-4 pt-3 ">
            <div class="float-start">
              <h5>Produtos</h5>
            </div>
            <div class="w-50">
              <input id="search" class="form-control" @change="list()" placeholder="Digite sua pesquisa"
                     type="text" v-model="search">
            </div>

            <div class="float-end ms-2">
              <button-widget cor="azul" :href="'/tabela_precos_produtos/create/'+tabela_preco_id" tamanho="M">
                Adicionar
              </button-widget>
            </div>
            <div class="float-end">
              <button-widget cor="azul" href="/tabela_precos/index" tamanho="M">
                Voltar
              </button-widget>
            </div>
          </div>

        </div>
        <table class="table">
          <thead>
          <tr>
            <th>Ações</th>
            <th></th>
          </tr>
          </thead>
          <tbody>
          <tr v-for="row in rows" :key="row.id">
            <td>
              <div class="dropdown">
                <button class="btn btn-system btn-sm dropdown-toggle" type="button" data-bs-toggle="dropdown"
                        aria-expanded="false">
                  Ações
                </button>
                <ul class="dropdown-menu">
                  <li>
                    <router-link class="dropdown-item" :to="'/tabela_precos_produtos/edit/'+row.id">
                      <i class="bi bi-pencil-square"></i>
                      Editar
                    </router-link>
                  </li>
                  <li>
                                        <span class="dropdown-item cursor-pointer" @click="deleteRow(row.id)">
                                            <i class="bi bi-trash2-fill"></i>
                                             Apagar

                                        </span>
                  </li>
                </ul>
              </div>


            </td>

            <td>
              <div class="col-12"><strong>Produto : </strong>{{ row.produto}}</div>
              <div class="col-12"><strong>Valor Mínimo : </strong>R$ {{ new Number(row.valor_minimo).toLocaleString('pt-BR', { minimumFractionDigits: 2 }) }}</div>
              <div class="col-12"><strong>Desconto Máximo : </strong>{{ new Number(row.desconto_maximo).toLocaleString('pt-BR', { minimumFractionDigits: 2 }) }}%</div>
            </td>
            <td></td>

          </tr>
          <tr v-if="rows==null ">
            <td colspan="2">
              <div class="row">
                <div class="col-12 d-flex justify-content-center">
                  <div class="loader"></div>
                </div>
              </div>
            </td>
          </tr>
          <tr v-if="rows===false ">
            <td colspan="2" class="text-center"> Não há dados</td>
          </tr>
          </tbody>
        </table>

      </div>
    </div>


  </layout-page>
</template>
<script>
import LayoutPage from "@/components/page/layoutPage.vue";
import ButtonWidget from "@/components/widget/buttonWidget.vue";
import toastr from "toastr/build/toastr.min";
import Helpers from "@/services/Helpers";
import tabela_precos_produtoService from "@/services/tabela_precos_produto.service";

export default {
  name: "IndexTabelaPrecosProdutos",
  components: {ButtonWidget, LayoutPage},
  data() {
    return {
      rows: null,
      search: null,
      tabela_preco_id: null
    }
  },
  methods: {
    async list() {

      let tabela_precos_produtosService = new tabela_precos_produtoService();
      let dataRow = await tabela_precos_produtosService.list(this.search, this.$route.params.id);
      let helpers = new Helpers();

      if (dataRow.data.data.length > 0) {
        this.rows = dataRow.data.data;

      } else if (!helpers.empty(dataRow.response?.data)) {
        toastr.error('Houve um problema');
      } else {
        this.rows = false;
      }


    },
    async deleteRow(id) {
      let tabela_precos_produtosService = new tabela_precos_produtoService();
      let dataRow = await tabela_precos_produtosService.delete(id);
      if (dataRow.data.success) {
        this.list();
        toastr.success('Apagado com sucesso');
      } else {
        toastr.error('Houve um problema ao apagar');
      }
    },
    indexTabelaProdutos() {
      this.tabela_preco_id = this.$route.params.id;
    }
  },
  created() {
    this.list();
    this.indexTabelaProdutos()

  }
}

</script>

<style scoped>
@import "toastr/build/toastr.css";
@import "bootstrap-icons/font/bootstrap-icons.min.css";
</style>
