<template>
  <layout-page>
    <div class="row">
      <div class="col-12 ps-4 pt-3 ">
        <div class="float-start">
          <h5>Editar Anexos</h5>
        </div>
        <div class="float-end">
          <button-widget cor="azul" :href="'/anexos/index/'+tipo+'/'+model_id" tamanho="M">
            Voltar
          </button-widget>
        </div>
      </div>

    </div>
    <div class="row">
      <FormAnexos></FormAnexos>
      <div class="col-4">
        <button class="btn btn-primary mt-4" type="button" @click="sendForm">Salvar</button>
      </div>
    </div>
  </layout-page>

</template>

<script>
import FormAnexos from "@/views/anexos/FormAnexos.vue";
import ButtonWidget from "@/components/widget/buttonWidget.vue";
import LayoutPage from "@/components/page/layoutPage.vue";
import toastr from "toastr/build/toastr.min";
import anexoService from "@/services/anexo.service";

export default {
  name: "EditAnexos",
  components: {LayoutPage, ButtonWidget, FormAnexos},
  data(){
    return{
      model_id:null,
      tipo:null,
    }
  },
  methods: {
    async edit(id) {
      let anexosService = new anexoService();
      let response = await anexosService.view(id);
      document.getElementById('nome').value = response.data.nome;
      document.getElementById('disponivel_ecommerce').value = response.data.disponivel_ecommerce;
      document.getElementById('descritivo').value = response.data.descritivo;
      this.tipo = response.data.tipo;
      this.model_id = response.data.model_id;

    },
    async sendForm() {
      let dataForm = {
        tipo: this.tipo,
        model_id: document.getElementById('model_id').value,
        nome: document.getElementById('nome').value,
        anexo: document.getElementById('anexo').value,
        disponivel_ecommerce: document.getElementById('disponivel_ecommerce').value,
        descritivo: document.getElementById('descritivo').value,
        _method: 'PUT'

      }
      if (!dataForm.parent_id) {
        delete dataForm.parent_id
      }
      let id = this.$route.params.id;
      let anexosService = new anexoService();
      let response = await anexosService.update(dataForm, id);
      if (response.data?.id) {
        toastr.success('Salvo com sucesso')
      } else {
        if (response.response.data?.message) {
          toastr.error(response.response.data?.message);
        } else {
          toastr.error('Houve um problema ao inserir');
        }

      }
    }
  },
  created() {
    this.edit(this.$route.params.id)
  }
}
</script>

