<template>
  <layout-page>
    <div class="row">
      <div class="col-12 ps-4 pt-3 ">
        <div class="float-start">
          <h5>Adicionar Pagamentos</h5>
        </div>
        <div class="float-end">
          <button-widget cor="azul" :href="'/conta_pagamentos/index/'+conta_id" tamanho="M">
            Voltar
          </button-widget>
        </div>
      </div>

    </div>
    <div class="row">
      <FormContaPagamentos></FormContaPagamentos>
      <div class="col-4">
        <button class="btn btn-primary mt-4" type="button" @click="sendForm">Salvar</button>
      </div>
    </div>
  </layout-page>
</template>
<script>
import ButtonWidget from "@/components/widget/buttonWidget.vue";
import LayoutPage from "@/components/page/layoutPage.vue";
import FormContaPagamentos from "@/views/conta_pagamentos/FormContaPagamentos.vue";
import conta_pagamentoService from "@/services/conta_pagamento.service";
import toastr from "toastr/build/toastr.min";

export default {
  name: "CreateContaPagamentos",
  components: {FormContaPagamentos, LayoutPage, ButtonWidget},
  data(){
    return {
      conta_id:null
    }
  },
  methods: {
    async sendForm() {
      let dataForm = {
        valor: document.getElementById('valor').value,
        tipo: document.getElementById('tipo').value,
        conta_id: this.conta_id,
        vencimento: document.getElementById('vencimento').value,
        payment_status: document.getElementById('payment_status').value,


      }
      let conta_pagamentosService = new conta_pagamentoService();
      let response = await conta_pagamentosService.store(dataForm);

      if (response.data?.id) {
        location.href = '/conta_pagamentos/index/'+this.conta_id;
      } else {
        if (response.response.data?.message) {
          toastr.error(response.response.data?.message);
        } else {
          toastr.error('Houve um problema ao inserir');
        }

      }
    }
  },
  mounted() {
    this.conta_id = this.$route.params.conta_id;
  }
}
</script>
